{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Orientin, a highly polar glycoside, showed low brain levels after IV administration in rats because of difficulty crossing the BBB; the query is an even larger, more polar glycoside, so passive CNS access is expected to be minimal.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Erythromycin, a large polar macrolide glycoside, achieved CSF concentrations only a small fraction of serum in humans after IV dosing, demonstrating that large polar glycosides do not gain meaningful CNS access; the query shares size and polarity liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Mithramycin, an anthracycline-like glycoside, showed a peak CSF:plasma ratio of only 0.12 in monkeys and little brain material, directly supporting poor CNS penetration for this structural class; the query is an anthracycline glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside, had a very low CSF/plasma ratio of 0.01-0.03 in dogs, indicating that glycosidic structures with multiple hydroxyls do not readily cross the BBB; the query has similar glycosidic polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "A fluorinated glucoside tracer with negative log P showed negligible brain uptake in mice; the query has a very negative logD and high TPSA, so even if efflux is inhibited by cyclosporine, passive permeability remains a major barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a doxorubicin-like anthracycline glycoside with very low passive BBB permeability and known P-gp liability. Although cyclosporine co-treatment may inhibit efflux, the consistent experimental evidence from polar glycosides and anthracycline glycosides indicates that brain/CSF exposure would remain inadequate for meaningful CNS access.",
  "evidence_gaps": [
    "No direct query-specific brain/plasma or CSF data under cyclosporine co-treatment",
    "Magnitude of P-gp inhibition on brain exposure is not quantified in the supplied evidence",
    "Potential active influx transporters or disease-state BBB changes are not assessed"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

